/* ============================================================
   Appointments timeline — resource table with a date filter
   ============================================================ */

.appt-filters { display: flex; align-items: center; gap: 12px; flex-wrap: wrap; margin-bottom: 14px; }

.appt-filters__label { font-size: 12.5px; font-weight: 700; color: var(--ink-2); }

.appt-filters__chips { display: flex; gap: 8px; flex-wrap: wrap; }

.appt-chip {
  display: inline-flex; align-items: center; gap: 7px;
  padding: 8px 14px; border-radius: var(--radius-pill);
  border: 1px solid var(--glass-border); background: rgba(var(--glass), .7);
  font: inherit; font-size: 13px; font-weight: 650; color: var(--ink); cursor: pointer;
}

.appt-chip:not(.appt-chip--on):hover { background: rgba(var(--glass), 1); border-color: var(--hair); }

.appt-chip--on { background: var(--accent); border-color: transparent; color: #fff; }

.appt-chip--on:hover { filter: brightness(1.06); }

.appt-chip__count {
  min-width: 20px; padding: 1px 6px; border-radius: var(--radius-pill);
  background: rgba(var(--hair), .18); font-size: 11.5px; font-weight: 800; text-align: center;
}

.appt-chip--on .appt-chip__count { background: rgba(255,255,255,.24); }

.appt { padding: 0; overflow: hidden; }

.appt__scroll { overflow-x: auto; }

.appt__table { width: 100%; border-collapse: collapse; font-size: 13.5px; }

.appt__table th {
  text-align: left; padding: 13px 18px; white-space: nowrap;
  font-size: 12px; font-weight: 750; letter-spacing: .03em; text-transform: uppercase;
  color: var(--ink-3); border-bottom: 1px solid var(--hair);
}

.appt__table td { padding: 13px 18px; border-bottom: 1px solid var(--hair); vertical-align: top; }

.appt__table tbody tr:last-child td { border-bottom: 0; }

.appt__table tbody tr:hover { background: rgba(var(--glass), .5); }

.appt__sort {
  display: inline-flex; align-items: center; gap: 6px;
  padding: 0; border: 0; background: transparent; cursor: pointer;
  font: inherit; color: inherit; letter-spacing: inherit; text-transform: inherit;
}

.appt__sort:hover { color: var(--accent); }

.appt__caret { font-size: 11px; color: var(--accent); }

.appt__resource { font-weight: 750; white-space: nowrap; }

.appt__name { font-weight: 650; }

.appt__table td:nth-child(2) { min-width: 210px; }

.appt__table td:nth-child(3) { min-width: 150px; }

.appt__sub { font-size: 12.5px; color: var(--ink-2); margin-top: 3px; }

.appt__time { font-variant-numeric: tabular-nums; white-space: nowrap; }

.appt__table tr[data-state="in_progress"] .appt__time { font-weight: 700; }

.appt__empty { padding: 22px 18px; }

.appt__count { font-size: 12.5px; color: var(--ink-3); margin-top: 12px; }

.appt__link {
  display: block; width: 100%; padding: 0; border: 0; background: transparent;
  font: inherit; color: inherit; text-align: left; cursor: pointer;
}

.appt__link .appt__name,
.appt__link .appt__sub { display: block; }

.appt__link:hover .appt__name { color: var(--accent); }

.appt__link:hover .status-badge { filter: brightness(.96); }

.ov-slot__link {
  display: block; flex: 1; min-width: 0; padding: 0; border: 0; background: transparent;
  font: inherit; color: inherit; text-align: left; cursor: pointer;
}

.ov-slot__link .ov-row__title,
.ov-slot__link .ov-row__meta { display: block; }

.ov-slot__link:hover .ov-row__title { color: var(--accent); }

.prop-head { display: flex; align-items: flex-start; gap: 14px; margin: 6px 0 18px; }

.prop-head__title { font-size: 30px; font-weight: 800; letter-spacing: -.03em; margin: 0; }

.prop-head__addr { font-size: 14px; color: var(--ink-2); margin-top: 5px; }

.prop-facts { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 16px 22px; margin-bottom: 16px; }

.prop-fact__label { font-size: 12px; font-weight: 700; letter-spacing: .03em; text-transform: uppercase; color: var(--ink-3); }

.prop-fact__value { font-size: 14.5px; font-weight: 650; margin-top: 4px; }

.prop-fact__note { font-size: 12.5px; color: var(--ink-2); margin-top: 3px; }

.prop-section__title { font-size: 12px; font-weight: 700; letter-spacing: .03em; text-transform: uppercase; color: var(--ink-3); margin-bottom: 10px; }

.prop-ticket { margin-bottom: 16px; }

.prop-ticket__title { font-weight: 700; font-size: 15px; margin-bottom: 8px; }

.prop-visit {
  display: flex; align-items: center; gap: 12px; width: 100%;
  padding: 12px; border-radius: var(--radius-md); border: 1px solid var(--hair);
